// [S4] Three-portal family features — join family by code.
import 'package:dio/dio.dart';
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class JoinFamilyScreen extends ConsumerStatefulWidget {
  const JoinFamilyScreen({super.key});

  @override
  ConsumerState<JoinFamilyScreen> createState() => _JoinFamilyScreenState();
}

class _JoinFamilyScreenState extends ConsumerState<JoinFamilyScreen> {
  final _codeController = TextEditingController();
  final _relationshipController = TextEditingController();
  final _messageController = TextEditingController();
  bool _submitting = false;
  String? _error;
  bool _sent = false;

  @override
  void dispose() {
    _codeController.dispose();
    _relationshipController.dispose();
    _messageController.dispose();
    super.dispose();
  }

  Future<void> _submit() async {
    final code = _codeController.text.trim();
    final relationship = _relationshipController.text.trim();
    if (code.isEmpty || relationship.isEmpty) {
      setState(() => _error = 'Enter the family code and your relationship.');
      return;
    }
    setState(() {
      _submitting = true;
      _error = null;
    });
    try {
      await ref.read(familyPortalApiProvider).joinFamilyByCode(
        familyCode: code,
        relationshipType: relationship,
        message: _messageController.text,
      );
      if (mounted) setState(() => _sent = true);
    } on DioException catch (error) {
      final status = error.response?.statusCode;
      setState(() {
        _error = switch (status) {
          404 => 'That family code was not found. Check it and try again.',
          409 => 'You already have a pending or existing request for this family.',
          _ => 'Could not send the join request. Try again.',
        };
      });
    } on Object {
      setState(() => _error = 'Could not send the join request. Try again.');
    } finally {
      if (mounted) setState(() => _submitting = false);
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    appBar: AppBar(title: const Text('Join family')),
    body: SafeArea(
      child: _sent
          ? const Center(
              child: Padding(
                padding: EdgeInsets.all(24),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(Icons.check_circle_outline, size: 48),
                    SizedBox(height: 12),
                    Text(
                      'Request sent',
                      style: TextStyle(fontWeight: FontWeight.w700, fontSize: 18),
                    ),
                    SizedBox(height: 8),
                    Text(
                      'The Family Head will review your request to join.',
                      textAlign: TextAlign.center,
                    ),
                  ],
                ),
              ),
            )
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                const Text(
                  'Ask your Family Head for the family code, then enter it below.',
                ),
                const SizedBox(height: 16),
                TextField(
                  controller: _codeController,
                  textCapitalization: TextCapitalization.characters,
                  decoration: const InputDecoration(
                    labelText: 'Family code',
                    hintText: 'FV-XXXXXX',
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _relationshipController,
                  decoration: const InputDecoration(
                    labelText: 'Your relationship to this family',
                    hintText: 'e.g. Spouse, Sibling',
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _messageController,
                  maxLength: 280,
                  maxLines: 3,
                  decoration: const InputDecoration(
                    labelText: 'Message (optional)',
                  ),
                ),
                if (_error != null) ...[
                  const SizedBox(height: 8),
                  Text(_error!, style: TextStyle(color: Theme.of(context).colorScheme.error)),
                ],
                const SizedBox(height: 16),
                ElevatedButton(
                  onPressed: _submitting ? null : _submit,
                  child: _submitting
                      ? const SizedBox(
                          width: 20,
                          height: 20,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : const Text('Send request'),
                ),
              ],
            ),
    ),
  );
}
